[patterns/application/api-microservices/PTN-APP-API-036-integration-testing-pattern.md#database-integration-testing-with-testcontainers]

### Database Integration Testing with Testcontainers

**PostgreSQL Integration Test Example**:

```java
package com.gainwell.member.service;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.time.LocalDate;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest  // Loads full Spring application context
@Testcontainers  // Activates Testcontainers JUnit 5 extension
public class MemberServiceIntegrationTest {

    // 1. Define PostgreSQL container
    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:14.2")
        .withDatabaseName("members_db")
        .withUsername("test_user")
        .withPassword("test_password")
        .withInitScript("db/init.sql");  // Optional: Initialize schema

    // 2. Override Spring properties with container connection details
    @DynamicPropertySource
    static void postgresProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired
    private MemberService memberService;

    @Autowired
    private MemberRepository memberRepository;

    // 3. Integration tests with REAL PostgreSQL

    @Test
    void shouldCreateMemberAndPersistToDatabase() {
        // Arrange
        String memberId = "M12345";
        String firstName = "John";
        String lastName = "Doe";
        LocalDate dateOfBirth = LocalDate.of(1985, 5, 15);

        // Act: Service method writes to REAL PostgreSQL container
        Member created = memberService.createMember(
            memberId, firstName, lastName, dateOfBirth
        );

        // Assert: Verify member saved correctly
        assertNotNull(created.getId());
        assertEquals(memberId, created.getMemberId());
        assertEquals(firstName, created.getFirstName());
        assertEquals(lastName, created.getLastName());
        assertEquals(dateOfBirth, created.getDateOfBirth());

        // Verify data actually exists in database
        Optional<Member> retrieved = memberRepository.findByMemberId(memberId);
        assertTrue(retrieved.isPresent());
        assertEquals("John", retrieved.get().getFirstName());
    }

    @Test
    void shouldEnforceUniqueMemberIdConstraint() {
        // Arrange: Create first member
        memberService.createMember("M12345", "John", "Doe", LocalDate.of(1985, 5, 15));

        // Act & Assert: Attempt to create duplicate member ID
        // REAL PostgreSQL enforces unique constraint
        assertThrows(DataIntegrityViolationException.class, () -> {
            memberService.createMember("M12345", "Jane", "Smith", LocalDate.of(1990, 3, 10));
        });
    }

    @Test
    void shouldHandleTransactionRollbackOnError() {
        // Arrange: Create valid member
        memberService.createMember("M12345", "John", "Doe", LocalDate.of(1985, 5, 15));

        // Act: Attempt update that fails mid-transaction
        assertThrows(RuntimeException.class, () -> {
            memberService.updateMemberWithError("M12345", "Updated Name");
            // Method updates member, then throws exception before commit
        });

        // Assert: Transaction rolled back, original data preserved
        Optional<Member> member = memberRepository.findByMemberId("M12345");
        assertTrue(member.isPresent());
        assertEquals("John", member.get().getFirstName());  // NOT "Updated Name"

        // REAL PostgreSQL transaction behavior tested (not mock)
    }

    @Test
    void shouldTestQueryPerformanceWithRealisticData() {
        // Arrange: Create 1000 members
        for (int i = 0; i < 1000; i++) {
            memberService.createMember(
                "M" + i,
                "FirstName" + i,
                "LastName" + i,
                LocalDate.of(1980, 1, 1).plusDays(i)
            );
        }

        // Act: Execute query and measure time
        long startTime = System.currentTimeMillis();
        List<Member> activeMembers = memberRepository.findByStatus("ACTIVE");
        long duration = System.currentTimeMillis() - startTime;

        // Assert: Query completes within performance threshold
        assertTrue(duration < 500, "Query took " + duration + "ms, expected <500ms");

        // REAL PostgreSQL query performance tested (indexes, explain plan)
    }

    @Test
    void shouldTestDatabaseMigrationWithFlyway() {
        // Testcontainers runs Flyway migrations automatically
        // This test verifies migrations applied successfully

        // Verify table exists (created by migration V1__create_members_table.sql)
        assertTrue(tableExists("members"));

        // Verify column exists (added by migration V2__add_phone_number.sql)
        assertTrue(columnExists("members", "phone_number"));

        // REAL Flyway migration scripts tested against PostgreSQL
    }
}
```

**What This Test Validates (That Mocks Cannot)**:
✓ SQL query correctness (syntax, joins, aggregations)
✓ Database constraints (unique, foreign key, NOT NULL, CHECK)
✓ Transaction isolation and rollback behavior
✓ Index performance and query optimization
✓ Database schema compatibility with code (ORM mappings)
✓ Connection pool configuration and exhaustion scenarios
✓ Database migration scripts (Flyway/Liquibase)

