### Message Broker Integration Testing (Kafka)

**Kafka Integration Test Example**:

```java
package com.gainwell.claims.service;

import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.KafkaContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import org.testcontainers.utility.DockerImageName;

import java.time.Duration;
import java.util.Collections;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

import static org.awaitility.Awaitility.await;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@Testcontainers
public class ClaimsKafkaIntegrationTest {

    // 1. Define Kafka container
    @Container
    static KafkaContainer kafka = new KafkaContainer(
        DockerImageName.parse("confluentinc/cp-kafka:7.3.0")
    );

    // 2. Configure Spring Kafka with container bootstrap servers
    @DynamicPropertySource
    static void kafkaProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.kafka.bootstrap-servers", kafka::getBootstrapServers);
    }

    @Autowired
    private ClaimsService claimsService;

    @Autowired
    private KafkaTemplate<String, String> kafkaTemplate;

    @Test
    void shouldPublishClaimSubmittedEventToKafka() throws Exception {
        // Arrange: Create consumer to verify event published
        KafkaConsumer<String, String> consumer = createConsumer("claim-submitted");

        // Act: Service publishes event to REAL Kafka container
        Claim claim = new Claim("CLM-12345", "M12345", BigDecimal.valueOf(150.00));
        claimsService.submitClaim(claim);

        // Assert: Verify event received from Kafka
        await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            assertFalse(records.isEmpty());

            ConsumerRecord<String, String> record = records.iterator().next();
            assertEquals("CLM-12345", record.key());
            assertTrue(record.value().contains("\"claimId\":\"CLM-12345\""));
            assertTrue(record.value().contains("\"amount\":150.00"));
        });
    }

    @Test
    void shouldConsumeClaimAdjudicatedEventAndUpdateDatabase() {
        // Arrange: Publish event to Kafka
        String claimId = "CLM-12345";
        String event = "{\"claimId\":\"CLM-12345\",\"status\":\"APPROVED\",\"amount\":150.00}";

        // Act: Publish to REAL Kafka container
        kafkaTemplate.send("claim-adjudicated", claimId, event).get();

        // Assert: Consumer processes event and updates database
        await().atMost(15, TimeUnit.SECONDS).untilAsserted(() -> {
            Claim claim = claimsRepository.findByClaimId(claimId).orElseThrow();
            assertEquals("APPROVED", claim.getStatus());
            assertEquals(BigDecimal.valueOf(150.00), claim.getAmount());
        });

        // REAL Kafka consumer behavior tested (not mock)
    }

    @Test
    void shouldHandleKafkaPartitioningWithKey() {
        // Arrange: Publish 100 events with different member IDs
        for (int i = 0; i < 100; i++) {
            String memberId = "M" + (i % 10);  // 10 unique member IDs
            String claimId = "CLM-" + i;
            String event = "{\"claimId\":\"" + claimId + "\",\"memberId\":\"" + memberId + "\"}";

            // Act: Publish with member ID as partition key
            kafkaTemplate.send("member-claims", memberId, event);
        }

        // Assert: Verify all events for same member ID went to same partition
        // (Kafka partition key strategy with REAL broker)
        KafkaConsumer<String, String> consumer = createConsumer("member-claims");

        Map<Integer, Set<String>> partitionToMemberIds = new HashMap<>();
        await().atMost(20, TimeUnit.SECONDS).untilAsserted(() -> {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
            records.forEach(record -> {
                int partition = record.partition();
                String memberId = extractMemberId(record.value());
                partitionToMemberIds
                    .computeIfAbsent(partition, k -> new HashSet<>())
                    .add(memberId);
            });

            // Each partition should have all events for specific member IDs
            // Same member ID never appears in multiple partitions
            partitionToMemberIds.forEach((partition, memberIds) -> {
                System.out.println("Partition " + partition + ": " + memberIds);
            });
        });

        // REAL Kafka partitioning tested (not mock)
    }

    @Test
    void shouldHandleKafkaMessageSerializationError() {
        // Arrange: Invalid JSON that will fail deserialization
        String invalidEvent = "{invalid json";

        // Act: Publish invalid message
        kafkaTemplate.send("claim-submitted", "CLM-ERROR", invalidEvent);

        // Assert: Error handler processes deserialization failure
        // Dead letter queue receives failed message
        await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> {
            KafkaConsumer<String, String> dlqConsumer = createConsumer("claim-submitted-dlq");
            ConsumerRecords<String, String> records = dlqConsumer.poll(Duration.ofSeconds(1));

            assertFalse(records.isEmpty());
            ConsumerRecord<String, String> record = records.iterator().next();
            assertEquals("{invalid json", record.value());
        });

        // REAL Kafka error handling tested (serialization, DLQ)
    }

    private KafkaConsumer<String, String> createConsumer(String topic) {
        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "test-consumer-" + UUID.randomUUID());
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);

        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);
        consumer.subscribe(Collections.singletonList(topic));
        return consumer;
    }
}
```

**What This Test Validates (That Mocks Cannot)**:
✓ Message publishing and consumption with real broker
✓ Kafka partition key strategy and message ordering
✓ Consumer group coordination and rebalancing
✓ Serialization/deserialization errors and error handling
✓ Dead letter queue (DLQ) routing for failed messages
✓ Exactly-once semantics configuration
✓ Topic auto-creation and broker configuration

