[patterns/application/api-microservices/PTN-APP-API-036-integration-testing-pattern.md#cache-integration-testing-redis]

### Cache Integration Testing (Redis)

**Redis Integration Test Example**:

```java
package com.gainwell.provider.service;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import org.testcontainers.utility.DockerImageName;

import java.time.Duration;
import java.util.concurrent.TimeUnit;

import static org.awaitility.Awaitility.await;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@Testcontainers
public class ProviderCacheIntegrationTest {

    // 1. Define Redis container
    @Container
    static GenericContainer<?> redis = new GenericContainer<>(
        DockerImageName.parse("redis:7.0-alpine")
    )
        .withExposedPorts(6379);

    // 2. Configure Spring Redis with container host and port
    @DynamicPropertySource
    static void redisProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.redis.host", redis::getHost);
        registry.add("spring.redis.port", redis::getFirstMappedPort);
    }

    @Autowired
    private ProviderService providerService;

    @Autowired
    private RedisTemplate<String, Provider> redisTemplate;

    @Test
    void shouldCacheProviderLookupInRedis() {
        // Arrange
        String npi = "1234567890";
        Provider provider = new Provider(npi, "Dr. Jane", "Smith", "Family Medicine");

        // Act: First lookup (cache miss, loads from database)
        long start1 = System.currentTimeMillis();
        Provider result1 = providerService.getProviderByNpi(npi);
        long duration1 = System.currentTimeMillis() - start1;

        // Second lookup (cache hit, loads from Redis)
        long start2 = System.currentTimeMillis();
        Provider result2 = providerService.getProviderByNpi(npi);
        long duration2 = System.currentTimeMillis() - start2;

        // Assert: Cache hit significantly faster
        assertTrue(duration2 < duration1 / 2,
            "Cache hit (" + duration2 + "ms) should be faster than miss (" + duration1 + "ms)");

        // Verify data cached in REAL Redis
        Provider cached = redisTemplate.opsForValue().get("provider:" + npi);
        assertNotNull(cached);
        assertEquals("Dr. Jane", cached.getFirstName());
    }

    @Test
    void shouldEvictCacheWhenProviderUpdated() {
        // Arrange: Cache provider
        String npi = "1234567890";
        providerService.getProviderByNpi(npi);  // Caches provider

        // Verify cached
        assertTrue(redisTemplate.hasKey("provider:" + npi));

        // Act: Update provider (should evict cache)
        providerService.updateProvider(npi, "Updated Specialty");

        // Assert: Cache evicted in REAL Redis
        assertFalse(redisTemplate.hasKey("provider:" + npi));
    }

    @Test
    void shouldExpireCacheAfterTTL() {
        // Arrange: Cache provider with 5-second TTL
        String npi = "1234567890";
        Provider provider = new Provider(npi, "Dr. Jane", "Smith", "Family Medicine");

        // Act: Cache with TTL
        redisTemplate.opsForValue().set("provider:" + npi, provider, Duration.ofSeconds(5));

        // Assert: Key exists initially
        assertTrue(redisTemplate.hasKey("provider:" + npi));

        // Wait for TTL expiration
        await().atMost(7, TimeUnit.SECONDS).untilAsserted(() -> {
            // Key expired and removed from REAL Redis
            assertFalse(redisTemplate.hasKey("provider:" + npi));
        });
    }

    @Test
    void shouldHandleRedisConnectionFailureGracefully() {
        // Simulate Redis unavailability by stopping container
        redis.stop();

        // Act & Assert: Service handles cache failure gracefully
        // Falls back to database lookup without crashing
        String npi = "1234567890";
        Provider provider = providerService.getProviderByNpi(npi);

        assertNotNull(provider);  // Data retrieved from database despite Redis down

        // Restart Redis for subsequent tests
        redis.start();
    }
}
```

**What This Test Validates (That Mocks Cannot)**:
✓ Cache hit/miss behavior with real Redis
✓ TTL expiration timing and eviction policies
✓ Cache serialization/deserialization format
✓ Redis connection pooling and failure handling
✓ Cache invalidation strategies
✓ Redis cluster failover (with Redis Sentinel/Cluster containers)

