[patterns/application/api-microservices/PTN-APP-API-036-integration-testing-pattern.md#external-api-integration-testing-wiremock]

### External API Integration Testing (WireMock)

**WireMock Container Test Example**:

```java
package com.gainwell.payment.service;

import com.github.tomakehurst.wiremock.client.WireMock;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import static com.github.tomakehurst.wiremock.client.WireMock.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@Testcontainers
public class PaymentExternalAPIIntegrationTest {

    // 1. Define WireMock container for external API simulation
    @Container
    static GenericContainer<?> wiremock = new GenericContainer<>("wiremock/wiremock:2.35.0")
        .withExposedPorts(8080)
        .withCommand("--global-response-templating");

    // 2. Configure external API URL to point to WireMock container
    @DynamicPropertySource
    static void wiremockProperties(DynamicPropertyRegistry registry) {
        String wiremockUrl = "http://" + wiremock.getHost() + ":" + wiremock.getFirstMappedPort();
        registry.add("payment.processor.api.url", () -> wiremockUrl);
    }

    @Autowired
    private PaymentService paymentService;

    @Test
    void shouldProcessPaymentViaExternalAPI() {
        // Arrange: Configure WireMock to simulate payment processor API
        WireMock wireMockClient = new WireMock(wiremock.getHost(), wiremock.getFirstMappedPort());

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .willReturn(aResponse()
                .withStatus(200)
                .withHeader("Content-Type", "application/json")
                .withBody("{\"transactionId\":\"TXN-12345\",\"status\":\"APPROVED\",\"amount\":150.00}")
            )
        );

        // Act: Service calls REAL HTTP endpoint (WireMock container)
        PaymentResult result = paymentService.processPayment("CLM-12345", BigDecimal.valueOf(150.00));

        // Assert: Payment processed successfully
        assertEquals("TXN-12345", result.getTransactionId());
        assertEquals("APPROVED", result.getStatus());
        assertEquals(BigDecimal.valueOf(150.00), result.getAmount());

        // Verify HTTP request made to WireMock
        wireMockClient.verifyThat(postRequestedFor(urlEqualTo("/api/v1/payments"))
            .withHeader("Content-Type", equalTo("application/json"))
            .withRequestBody(matchingJsonPath("$.claimId", equalTo("CLM-12345")))
            .withRequestBody(matchingJsonPath("$.amount", equalTo("150.00")))
        );
    }

    @Test
    void shouldHandleExternalAPITimeout() {
        // Arrange: Configure WireMock to simulate timeout (delay > timeout threshold)
        WireMock wireMockClient = new WireMock(wiremock.getHost(), wiremock.getFirstMappedPort());

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .willReturn(aResponse()
                .withStatus(200)
                .withFixedDelay(10000)  // 10-second delay (exceeds 5-second timeout)
            )
        );

        // Act & Assert: Service handles timeout gracefully
        assertThrows(PaymentTimeoutException.class, () -> {
            paymentService.processPayment("CLM-12345", BigDecimal.valueOf(150.00));
        });

        // REAL HTTP timeout behavior tested (not mock)
    }

    @Test
    void shouldRetryOnTransientErrors() {
        // Arrange: Configure WireMock to fail twice, then succeed
        WireMock wireMockClient = new WireMock(wiremock.getHost(), wiremock.getFirstMappedPort());

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .inScenario("Retry Scenario")
            .whenScenarioStateIs(STARTED)
            .willReturn(aResponse().withStatus(503))  // First attempt: 503 Service Unavailable
            .willSetStateTo("First Retry")
        );

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .inScenario("Retry Scenario")
            .whenScenarioStateIs("First Retry")
            .willReturn(aResponse().withStatus(500))  // Second attempt: 500 Internal Server Error
            .willSetStateTo("Second Retry")
        );

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .inScenario("Retry Scenario")
            .whenScenarioStateIs("Second Retry")
            .willReturn(aResponse()
                .withStatus(200)  // Third attempt: Success
                .withBody("{\"transactionId\":\"TXN-12345\",\"status\":\"APPROVED\"}")
            )
        );

        // Act: Service retries failed requests
        PaymentResult result = paymentService.processPayment("CLM-12345", BigDecimal.valueOf(150.00));

        // Assert: Eventually succeeds after retries
        assertEquals("APPROVED", result.getStatus());

        // Verify 3 requests made (initial + 2 retries)
        wireMockClient.verifyThat(3, postRequestedFor(urlEqualTo("/api/v1/payments")));

        // REAL HTTP retry logic tested (exponential backoff, retry limits)
    }

    @Test
    void shouldHandleRateLimiting() {
        // Arrange: Configure WireMock to return 429 Too Many Requests
        WireMock wireMockClient = new WireMock(wiremock.getHost(), wiremock.getFirstMappedPort());

        wireMockClient.register(post(urlEqualTo("/api/v1/payments"))
            .willReturn(aResponse()
                .withStatus(429)
                .withHeader("Retry-After", "60")
            )
        );

        // Act & Assert: Service handles rate limiting
        assertThrows(PaymentRateLimitException.class, () -> {
            paymentService.processPayment("CLM-12345", BigDecimal.valueOf(150.00));
        });

        // REAL HTTP 429 handling tested (retry-after header)
    }
}
```

**What This Test Validates (That Mocks Cannot)**:
✓ HTTP request/response format and serialization
✓ Timeout handling with real network delays
✓ Retry logic with exponential backoff
✓ Circuit breaker behavior after failure threshold
✓ Rate limiting (429 Too Many Requests) handling
✓ Error response parsing (400, 401, 403, 500, 503)
✓ Request/response logging and monitoring

