@SpringBootTest
@Testcontainers
class MemberServiceDatabaseIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:14.2")
        .withDatabaseName("members_test")
        .withInitScript("db/schema.sql");  // Initialize schema

    @DynamicPropertySource
    static void props(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired
    private MemberService memberService;

    @Autowired
    private MemberRepository memberRepository;

    @Test
    void shouldHandleTransactionRollbackOnError() {
        // Test database transaction behavior
        Member member = memberService.createMember("M001", "John", "Doe", LocalDate.of(1985, 1, 1));

        // Update fails mid-transaction
        assertThrows(RuntimeException.class, () -> {
            memberService.updateMemberNameWithError("M001", "Updated Name");
        });

        // Verify transaction rolled back
        Member retrieved = memberRepository.findByMemberId("M001").orElseThrow();
        assertEquals("John", retrieved.getFirstName());  // Original value, not updated
    }

    @Test
    void shouldEnforceForeignKeyConstraints() {
        // Create member with eligibility record (foreign key relationship)
        Member member = memberService.createMember("M002", "Jane", "Smith", LocalDate.of(1990, 5, 15));
        Eligibility eligibility = eligibilityService.createEligibility(member.getId(), "ACTIVE");

        // Attempt to delete member (should fail due to foreign key constraint)
        assertThrows(DataIntegrityViolationException.class, () -> {
            memberRepository.deleteById(member.getId());
        });
    }

    @Test
    void shouldTestQueryPerformanceWithIndexes() {
        // Create 10,000 members
        for (int i = 0; i < 10000; i++) {
            memberService.createMember("M" + i, "First" + i, "Last" + i, LocalDate.of(1980, 1, 1));
        }

        // Query with index on last_name
        long start = System.currentTimeMillis();
        List<Member> results = memberRepository.findByLastName("Last5000");
        long duration = System.currentTimeMillis() - start;

        // Should complete quickly with index
        assertTrue(duration < 100, "Query took " + duration + "ms, expected <100ms");
    }

    @Test
    void shouldTestConnectionPoolExhaustion() {
        // Simulate 100 concurrent database connections
        ExecutorService executor = Executors.newFixedThreadPool(100);
        CountDownLatch latch = new CountDownLatch(100);

        for (int i = 0; i < 100; i++) {
            final int id = i;
            executor.submit(() -> {
                try {
                    memberService.createMember("M" + id, "First", "Last", LocalDate.now());
                } finally {
                    latch.countDown();
                }
            });
        }

        // All requests should complete (connection pool configured correctly)
        assertTrue(latch.await(30, TimeUnit.SECONDS));
    }
}
```

**Claims Service: Kafka Integration Tests**

File: `ClaimsServiceKafkaIntegrationTest.java`

```java
@SpringBootTest
@Testcontainers
class ClaimsServiceKafkaIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:14.2");

    @Container
    static KafkaContainer kafka = new KafkaContainer(
        DockerImageName.parse("confluentinc/cp-kafka:7.3.0")
    );

    @DynamicPropertySource
    static void props(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.kafka.bootstrap-servers", kafka::getBootstrapServers);
    }

    @Autowired
    private ClaimsService claimsService;

    @Test
    void shouldPublishClaimSubmittedEvent() {
        // Create consumer to verify event
        KafkaConsumer<String, String> consumer = createConsumer("claim-submitted");

        // Submit claim (publishes event)
        Claim claim = claimsService.submitClaim("M001", BigDecimal.valueOf(150.00));

        // Verify event published
        await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            assertFalse(records.isEmpty());

            ConsumerRecord<String, String> record = records.iterator().next();
            assertTrue(record.value().contains("\"claimId\":\"" + claim.getClaimId() + "\""));
        });
    }

    @Test
    void shouldMaintainMessageOrderingWithinPartition() {
        // Publish 100 events for same member (same partition key)
        String memberId = "M001";
        for (int i = 0; i < 100; i++) {
            claimsService.submitClaim(memberId, BigDecimal.valueOf(i * 10));
        }

        // Consume events and verify ordering
        KafkaConsumer<String, String> consumer = createConsumer("claim-submitted");
        List<Integer> receivedAmounts = new ArrayList<>();

        await().atMost(30, TimeUnit.SECONDS).untilAsserted(() -> {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
            records.forEach(record -> {
                int amount = extractAmount(record.value());
                receivedAmounts.add(amount);
            });

            assertEquals(100, receivedAmounts.size());
        });

        // Verify messages received in order (0, 10, 20, ..., 990)
        for (int i = 0; i < 100; i++) {
            assertEquals(i * 10, receivedAmounts.get(i));
        }
    }

    @Test
    void shouldHandleDeadLetterQueueForFailedMessages() {
        // Publish invalid message (malformed JSON)
        kafkaTemplate.send("claim-submitted", "INVALID", "{malformed json");

        // Verify DLQ receives failed message
        KafkaConsumer<String, String> dlqConsumer = createConsumer("claim-submitted-dlq");

        await().atMost(15, TimeUnit.SECONDS).untilAsserted(() -> {
            ConsumerRecords<String, String> records = dlqConsumer.poll(Duration.ofSeconds(1));
            assertFalse(records.isEmpty());
        });
    }
}
```

