        wireMockClient.register(get(urlPathEqualTo("/api/licenses/MD-12345"))
            .inScenario("Retry")
            .whenScenarioStateIs(STARTED)
            .willReturn(aResponse().withStatus(503))
            .willSetStateTo("First Retry")
        );

        wireMockClient.register(get(urlPathEqualTo("/api/licenses/MD-12345"))
            .inScenario("Retry")
            .whenScenarioStateIs("First Retry")
            .willReturn(aResponse().withStatus(500))
            .willSetStateTo("Second Retry")
        );

        wireMockClient.register(get(urlPathEqualTo("/api/licenses/MD-12345"))
            .inScenario("Retry")
            .whenScenarioStateIs("Second Retry")
            .willReturn(aResponse()
                .withStatus(200)
                .withBody("{\"licenseNumber\":\"MD-12345\",\"status\":\"ACTIVE\"}")
            )
        );

        // Should eventually succeed
        ProviderLicenseStatus status = providerService.verifyProviderLicense("MD-12345");
        assertEquals("ACTIVE", status.getStatus());

        // Verify 3 requests made
        wireMockClient.verifyThat(3, getRequestedFor(urlPathEqualTo("/api/licenses/MD-12345")));
    }
