**Provider Service: Redis Cache Integration**

```java
@SpringBootTest
@Testcontainers
class ProviderCacheIntegrationTest {

    @Container
    static GenericContainer<?> redis = new GenericContainer<>("redis:7.0-alpine")
        .withExposedPorts(6379);

    @DynamicPropertySource
    static void props(DynamicPropertyRegistry registry) {
        registry.add("spring.redis.host", redis::getHost);
        registry.add("spring.redis.port", redis::getFirstMappedPort);
    }

    @Autowired
    private ProviderService providerService;

    @Autowired
    private RedisTemplate<String, Provider> redisTemplate;

    @Test
    void shouldCacheProviderLookup() {
        String npi = "1234567890";

        // First lookup (miss, loads from database)
        long start1 = System.currentTimeMillis();
        Provider provider1 = providerService.getProviderByNpi(npi);
        long duration1 = System.currentTimeMillis() - start1;

        // Second lookup (hit, loads from Redis cache)
        long start2 = System.currentTimeMillis();
        Provider provider2 = providerService.getProviderByNpi(npi);
        long duration2 = System.currentTimeMillis() - start2;

        // Cache hit should be significantly faster
        assertTrue(duration2 < duration1 / 3);

        // Verify cached in Redis
        Provider cached = redisTemplate.opsForValue().get("provider:" + npi);
        assertNotNull(cached);
    }

    @Test
    void shouldEvictCacheOnUpdate() {
        String npi = "1234567890";

        // Cache provider
        providerService.getProviderByNpi(npi);
        assertTrue(redisTemplate.hasKey("provider:" + npi));

        // Update provider
        providerService.updateProviderSpecialty(npi, "Cardiology");

        // Cache should be evicted
        assertFalse(redisTemplate.hasKey("provider:" + npi));
    }

    @Test
    void shouldExpireCacheAfterTTL() {
        String npi = "1234567890";
        Provider provider = new Provider(npi, "Dr. Jane", "Smith");

        // Cache with 5-second TTL
        redisTemplate.opsForValue().set("provider:" + npi, provider, Duration.ofSeconds(5));

        // Key exists initially
        assertTrue(redisTemplate.hasKey("provider:" + npi));

        // Wait for TTL expiration
        await().atMost(7, TimeUnit.SECONDS).untilAsserted(() -> {
            assertFalse(redisTemplate.hasKey("provider:" + npi));
        });
    }
}
```

