**Test Data Builders Pattern**

Create reusable test data builders to simplify test setup:

File: `src/test/java/com/gainwell/testdata/MemberTestDataBuilder.java`

```java
package com.gainwell.testdata;

public class MemberTestDataBuilder {
    private String memberId = "M" + UUID.randomUUID().toString().substring(0, 8);
    private String firstName = "John";
    private String lastName = "Doe";
    private LocalDate dateOfBirth = LocalDate.of(1985, 1, 1);
    private String status = "ACTIVE";

    public static MemberTestDataBuilder aMember() {
        return new MemberTestDataBuilder();
    }

    public MemberTestDataBuilder withMemberId(String memberId) {
        this.memberId = memberId;
        return this;
    }

    public MemberTestDataBuilder withName(String firstName, String lastName) {
        this.firstName = firstName;
        this.lastName = lastName;
        return this;
    }

    public MemberTestDataBuilder withDateOfBirth(LocalDate dateOfBirth) {
        this.dateOfBirth = dateOfBirth;
        return this;
    }

    public MemberTestDataBuilder active() {
        this.status = "ACTIVE";
        return this;
    }

    public MemberTestDataBuilder inactive() {
        this.status = "INACTIVE";
        return this;
    }

    public Member build() {
        return new Member(memberId, firstName, lastName, dateOfBirth, status);
    }

    public Member buildAndSave(MemberRepository repository) {
        return repository.save(build());
    }
}
```

